  function drawRock(rock,isTarget,label){const info=rockInfo[rock.type]||rockInfo.common;ctx.save();ctx.translate(rock.x,rock.y);ctx.fillStyle=rock.type==='boss'?'#8f2924':isTarget?'#773f30':info.color;ctx.strokeStyle=isTarget?'#ffcc4d':'#303435';ctx.lineWidth=isTarget?4:2;ctx.beginPath();if(rock.type==='boss'){for(let i=0;i<24;i++){const a=i*Math.PI/12,r=i%2?rock.r*.82:rock.r;ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r)}ctx.closePath()}else if(rock.type==='fast'){ctx.moveTo(rock.r,0);ctx.lineTo(0,rock.r*.72);ctx.lineTo(-rock.r,0);ctx.lineTo(0,-rock.r*.72);ctx.closePath()}else if(rock.type==='armored'){for(let i=0;i<6;i++){const a=i*Math.PI/3;ctx.lineTo(Math.cos(a)*rock.r,Math.sin(a)*rock.r)}ctx.closePath()}else if(rock.type==='fragmenter'){for(let i=0;i<10;i++){const a=i*Math.PI/5,r=i%2?rock.r*.78:rock.r;ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r)}ctx.closePath()}else{ctx.arc(0,0,rock.r,0,Math.PI*2)}ctx.fill();ctx.stroke();if(rock.type==='boss'){ctx.beginPath();ctx.arc(0,0,rock.r*.6,0,Math.PI*2);ctx.strokeStyle='#ffb23e';ctx.lineWidth=5;ctx.stroke();ctx.fillStyle='#ffd269';ctx.font=`bold ${Math.max(20,rock.r*.48)}px Arial`;ctx.textAlign='center';ctx.fillText('♛',0,8)}else if(rock.type==='regenerator'){ctx.strokeStyle='#8df0a1';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,rock.r*.68,0,Math.PI*2);ctx.stroke()}if(rock.type!=='boss'){ctx.fillStyle='#fff';ctx.font=`bold ${Math.max(9,Math.min(13,rock.r*.55))}px Arial`;ctx.textAlign='center';ctx.fillText(String(label),0,4);ctx.fillStyle='#fff9';ctx.font='bold 8px Arial';ctx.fillText(info.symbol,0,rock.r*.62)}ctx.fillStyle='#311';ctx.fillRect(-rock.r,-rock.r-9,rock.r*2,4);ctx.fillStyle=rock.type==='boss'?'#ffb23e':rock.type==='regenerator'?'#7eed91':'#6ed18e';ctx.fillRect(-rock.r,-rock.r-9,rock.r*2*(rock.hp/rock.maxHp),4);ctx.restore()}
  function draw(){ctx.save();if(state.shake)ctx.translate(random(-6,6),random(-4,4));const scene=sceneFor(state.stage),colors=scene.colors,gradient=ctx.createLinearGradient(0,0,0,canvas.height);gradient.addColorStop(0,colors[0]);gradient.addColorStop(1,colors[1]);ctx.fillStyle=gradient;ctx.fillRect(0,0,canvas.width,canvas.height);ctx.strokeStyle=colors[4]+'44';ctx.lineWidth=1;for(let y=50;y<canvas.height;y+=50){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(canvas.width,y);ctx.stroke()}
    drawSceneDecor(scene);
    if(stageRules().haze){ctx.save();ctx.globalAlpha=.08+.07*(.5+.5*Math.sin(state.totalTime*.7));ctx.fillStyle='#f8d78c';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.restore()}
    ctx.fillStyle=colors[2];ctx.fillRect(0,0,36,canvas.height);ctx.fillStyle=colors[3];ctx.fillRect(36,0,13,canvas.height);ctx.fillStyle=colors[2];ctx.fillRect(canvas.width-42,0,42,canvas.height);
    const count=cannonCount(),spacing=canvas.height/count;for(let i=0;i<count;i++){const y=spacing*(i+.5);drawEnemyCannon(canvas.width-65,y,scene);if(state.enemyFlashes?.[i]){ctx.save();ctx.globalAlpha=state.enemyFlashes[i]*4;ctx.fillStyle='#fff3a0';ctx.shadowBlur=28;ctx.shadowColor='#ff8a35';ctx.beginPath();ctx.arc(canvas.width-92,y,10+state.enemyFlashes[i]*35,0,Math.PI*2);ctx.fill();ctx.restore()}}
    ctx.fillStyle='#263d4b';ctx.fillRect(38,state.cannon.y-8,35,16);ctx.beginPath();ctx.arc(state.cannon.x,state.cannon.y,state.cannon.r,0,Math.PI*2);ctx.fillStyle='#df522f';ctx.fill();ctx.lineWidth=5;ctx.strokeStyle='#72271f';ctx.stroke();ctx.fillStyle='#ffe4a0';ctx.font='bold 11px Arial';ctx.textAlign='center';ctx.fillText('QQ',state.cannon.x,state.cannon.y+4);
    const ordered=state.rocks.filter(rock=>rock.type!=='bossShot').sort((a,b)=>a.order-b.order),ranks=new Map(ordered.map((rock,index)=>[rock,index+1])),target=ordered[0];state.rocks.forEach(rock=>{ctx.save();ctx.globalAlpha=.18;ctx.strokeStyle=(rockInfo[rock.type]||rockInfo.common).color;ctx.lineWidth=Math.max(3,rock.r*.35);ctx.beginPath();ctx.moveTo(rock.x+rock.r,rock.y);ctx.lineTo(rock.x+rock.r+Math.min(70,rock.speed*.35),rock.y);ctx.stroke();ctx.restore();drawRock(rock,rock===target,rock.type==='bossShot'?'!':ranks.get(rock))});if(target&&target.x-target.r<230){ctx.save();ctx.globalAlpha=.38+.25*Math.sin(state.totalTime*10);ctx.strokeStyle='#ff392f';ctx.lineWidth=6;ctx.strokeRect(49,4,175,canvas.height-8);ctx.fillStyle='#ff392f';ctx.font='bold 15px Arial';ctx.textAlign='left';ctx.fillText('⚠ PERIGO',62,24);ctx.restore()}
    state.powerups.forEach(power=>{const info=powerInfo[power.type],pulse=1+Math.sin(power.phase)*.12;ctx.save();ctx.translate(power.x,power.y);ctx.scale(pulse,pulse);ctx.shadowBlur=18;ctx.shadowColor=info.color;ctx.fillStyle='#102b38';ctx.strokeStyle=info.color;ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,0,power.r,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle=info.color;ctx.font='bold 17px Arial';ctx.textAlign='center';ctx.fillText(info.icon,0,6);ctx.restore()});state.bullets.forEach(b=>{ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,Math.PI*2);ctx.fillStyle=state.totalTime<state.effects.pierceUntil?'#d9a3ff':'#fff7cf';ctx.shadowBlur=10;ctx.shadowColor=state.totalTime<state.effects.pierceUntil?'#a94dff':'#ff7b3e';ctx.fill();ctx.shadowBlur=0});state.sparks.forEach(s=>{ctx.globalAlpha=clamp(s.life*2,0,1);ctx.fillStyle=s.color;ctx.fillRect(s.x,s.y,4,4)});ctx.globalAlpha=1;ctx.restore()}
  function loop(now){const dt=Math.min(.035,(now-last)/1000||0);last=now;update(dt);draw();raf=requestAnimationFrame(loop)}
  function medalRank(value){return{bronze:1,silver:2,gold:3}[value]||0}
  function beginStage(stage,checkpoint=state.score){state.running=true;state.over=false;state.transitioning=false;state.overtime=false;state.bossDefeated=false;state.stage=clamp(stage,1,100);state.score=checkpoint;state.stageStartScore=checkpoint;state.stageTime=0;state.stageHits=0;state.stageShots=0;state.stageDestroyed=0;state.damageTaken=0;state.health=3;state.combo=1;state.stageMaxCombo=1;state.maxCombo=Math.max(1,state.maxCombo);state.spawnClock=0;state.sequence=0;state.activeTargetOrder=null;state.effects={doubleUntil:0,rapidUntil:0,pierceUntil:0,shield:0};state.bullets=[];state.rocks=[];state.powerups=[];state.sparks=[];state.stageStartDestroyed=state.totalDestroyed;state.stageStartDestroyedByType={...state.destroyedByType};state.stageStartBosses=state.bossesDefeated;state.stageStartPerfect=state.perfectDefenses;fireHeld=false;result.panel.hidden=true;ui.shell.classList.remove('stage-clear','game-over');ui.difficulty.disabled=true;ui.arcadeScene.disabled=true;ui.start.disabled=false;ui.start.textContent=state.playMode==='campaign'?'Reiniciar fase':'Reiniciar modo';updatePowerHud();if(state.playMode==='campaign'&&isBossStage(state.stage))spawnBoss();else ui.announcement.textContent=`FASE ${state.stage} · destrua primeiro a pedra marcada com 1!`;updateHud()}
  function showStageResult(data){const scene=sceneFor(state.stage),finalStage=state.stage===100;result.sector.textContent=`FASE ${state.stage} · ${scene.name}`;result.title.textContent=finalStage?'Campanha concluída!':'Defesa concluída!';result.medal.textContent=data.medal==='gold'?'🥇':data.medal==='silver'?'🥈':'🥉';result.points.textContent='+'+data.stagePoints;result.accuracy.textContent=data.accuracy+'%';result.destroyed.textContent=state.stageDestroyed;result.combo.textContent='x'+state.stageMaxCombo;result.health.textContent=state.health;result.bonus.textContent='+'+data.bonus;result.message.textContent=data.perfect?'Defesa perfeita: nenhuma energia perdida!':`Você sobreviveu com ${state.health} de 3 energias.`;result.next.textContent=finalStage?'Ver Hall dos Defensores':'Próxima fase';result.newCampaign.hidden=!finalStage;result.pause.hidden=finalStage;result.retry.textContent=finalStage?'Repetir fase 100':'Repetir fase';result.panel.hidden=false}
  function completeStage(){if(state.transitioning)return;if(isBossStage(state.stage)&&!state.bossDefeated){state.overtime=true;state.stageTime=Math.max(state.stageTime,stageDuration(state.stage));state.rocks=state.rocks.filter(rock=>rock.type==='boss');state.powerups=[];fireHeld=false;ui.announcement.textContent='TEMPO EXTRA · o chefe ainda está vivo e precisa ser eliminado!';updatePowerHud();updateHud();return}state.running=false;state.transitioning=true;fireHeld=false;state.bullets=[];state.rocks=[];state.powerups=[];const perfect=state.damageTaken===0,accuracy=Math.min(100,Math.round((state.stageShots?state.stageHits/state.stageShots:1)*100)),bonus=perfect?500*state.stage:0,stagePoints=state.score-state.stageStartScore+bonus,medal=perfect&&accuracy>=85?'gold':accuracy>=60?'silver':'bronze';state.score+=bonus;if(perfect)state.perfectDefenses++;state.bestAccuracy=Math.max(state.bestAccuracy,accuracy);const old=loadCampaign(),oldMedal=old.medals?.[state.stage],medals={...(old.medals||{})};if(medalRank(medal)>medalRank(oldMedal))medals[state.stage]=medal;const next=Math.min(100,state.stage+1);saveCampaign({currentStage:next,unlockedStage:Math.max(old.unlockedStage,next),medals});if(state.stage===100)registerRanking(true);else renderHall();ui.shell.classList.add('stage-clear');ui.announcement.textContent=`FASE ${state.stage} CONCLUÍDA · desempenho registrado.`;ui.start.disabled=true;tone(740,.12,'square',.05);tone(980,.2,'triangle',.04);updateHud();showStageResult({perfect,accuracy,bonus,stagePoints,medal})}
  function restoreSurvival(){try{const saved=JSON.parse(localStorage.getItem(SURVIVAL_KEY)||'null');if(!saved?.state)return false;state={...fresh(saved.state.stage),...saved.state,running:true,over:false,playMode:'survival'};ui.difficulty.value=saved.difficulty||'easy';ui.arcadeScene.value=String(state.stage);ui.gameMode.value='survival';ui.gameMode.disabled=true;ui.difficulty.disabled=true;ui.arcadeScene.disabled=true;ui.start.textContent='Reiniciar sobrevivência';ui.pauseSurvival.textContent='Pausar e continuar depois';ui.announcement.textContent=`SOBREVIVÊNCIA RETOMADA · onda ${state.wave}.`;last=performance.now();updatePowerHud();updateHud();return true}catch{localStorage.removeItem(SURVIVAL_KEY);return false}}
  function start(){const mode=ui.gameMode.value;if(mode!=='campaign'){if(mode==='survival'&&restoreSurvival()){ui.start.blur();return}const chosenStage=clamp(Number(ui.arcadeScene.value)||1,1,100);state=fresh(chosenStage);state.playMode=mode;beginStage(chosenStage,0);ui.gameMode.disabled=true;ui.start.blur();ui.announcement.textContent=mode==='survival'?'SOBREVIVÊNCIA · resista ao maior número de ondas!':mode==='timed'?'PARTIDA POR TEMPO · faça o máximo de pontos em 60 segundos!':'TREINO LIVRE · pratique sem perder energia.';return}const campaign=loadCampaign(),stage=state.over?state.stage:campaign.currentStage,checkpoint=state.over?state.stageStartScore:campaign.score||0;if(state.over){state.totalDestroyed=state.stageStartDestroyed;state.destroyedByType={...state.stageStartDestroyedByType};state.bossesDefeated=state.stageStartBosses;state.perfectDefenses=state.stageStartPerfect}state.playMode='campaign';beginStage(stage,checkpoint);ui.gameMode.disabled=true;ui.start.blur()}
  function gameOver(){state.running=false;state.over=true;fireHeld=false;if(state.playMode==='campaign'){state.totalDestroyed=state.stageStartDestroyed;state.destroyedByType={...state.stageStartDestroyedByType};state.bossesDefeated=state.stageStartBosses;state.perfectDefenses=state.stageStartPerfect}if(state.playMode==='survival'){registerArcadeResult(true);localStorage.removeItem(SURVIVAL_KEY)}ui.shell.classList.add('game-over');ui.gameMode.disabled=false;ui.difficulty.disabled=false;ui.arcadeScene.disabled=false;ui.pauseSurvival.textContent='Pausar e continuar depois';ui.announcement.textContent=state.playMode==='survival'?`SOBREVIVÊNCIA ENCERRADA NA ONDA ${state.wave} · ${state.score.toLocaleString('pt-BR')} pontos.`:`DEFESA ROMPIDA NA FASE ${state.stage} · tente novamente a partir desta fase.`;ui.start.textContent=state.playMode==='campaign'?'Repetir fase':'Jogar novamente'}
