  function renderTutorial(){const [icon,title,text]=tutorialSteps[tutorialIndex];tutorial.icon.textContent=icon;tutorial.title.textContent=title;tutorial.text.textContent=text;tutorial.step.textContent=`PASSO ${tutorialIndex+1} DE ${tutorialSteps.length}`;tutorial.progress.style.width=`${(tutorialIndex+1)/tutorialSteps.length*100}%`;tutorial.back.disabled=tutorialIndex===0;tutorial.next.textContent=tutorialIndex===tutorialSteps.length-1?'Concluir':'Próximo'}
