  addEventListener('keydown',e=>{if(!tutorial.overlay.hidden){if(e.code==='Escape')closeTutorial();if(e.code==='ArrowLeft')tutorial.back.click();if(e.code==='ArrowRight'||e.code==='Enter')tutorial.next.click();return}if(['ArrowUp','ArrowDown','Space'].includes(e.code))e.preventDefault();if(e.code==='ArrowUp')moveDirection=-1;if(e.code==='ArrowDown')moveDirection=1;if(e.code==='Space'&&!e.repeat){fireHeld=true;fire()}});addEventListener('keyup',e=>{if(!tutorial.overlay.hidden)return;if(['ArrowUp','ArrowDown','Space'].includes(e.code))e.preventDefault();if(['ArrowUp','ArrowDown'].includes(e.code))moveDirection=0;if(e.code==='Space')fireHeld=false});canvas.addEventListener('pointerdown',e=>{const rect=canvas.getBoundingClientRect();state.cannon.y=clamp((e.clientY-rect.top)*canvas.height/rect.height,38,canvas.height-38)});canvas.addEventListener('pointermove',e=>{if(e.buttons){const rect=canvas.getBoundingClientRect();state.cannon.y=clamp((e.clientY-rect.top)*canvas.height/rect.height,38,canvas.height-38)}});
