  populateArcadeScenes();const storedArcadeStage=clamp(Number(localStorage.getItem('qqfArcadeScene'))||1,1,100),storedArcadeScreen=Math.floor((storedArcadeStage-1)/10)*10+1;ui.arcadeScene.value=String(storedArcadeScreen);localStorage.setItem('qqfArcadeScene',String(storedArcadeScreen));ui.rankingName.value=localStorage.getItem('qqfPlayerName')||'Defensor';renderHall();ui.restartCampaign.hidden=!(loadCampaign().currentStage>=100&&loadCampaign().score>0);refreshModeControls();updateHud();draw();raf=requestAnimationFrame(loop);if(!localStorage.getItem('qqfTutorialV1'))setTimeout(openTutorial,500);
